package com.tapeverify.copilot.entity; import jakarta.persistence.*; import lombok.*; import java.time.LocalDateTime;
@Entity @Table(name="verified_loans") @Data @Builder @NoArgsConstructor @AllArgsConstructor public class VerifiedLoan {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @OneToOne(fetch=FetchType.LAZY) @JoinColumn(name="loan_id",nullable=false,unique=true) private Loan loan; @Column(name="verified_by",nullable=false) private String verifiedBy; @Column(name="verified_at",nullable=false) private LocalDateTime verifiedAt; @Column(nullable=false) private String decision; @Lob @Column(name="canonical_details",nullable=false,columnDefinition="LONGTEXT") private String canonicalDetails; @Column(name="record_hash",nullable=false,length=64) private String recordHash;}
